/* Upgrade layer: preserves the original furniture library, SVG gestures and history. */
const C=PlanCore;
let structTool='pick',draft=[],structureDrag=null,sourceOpacity=.38,reviewOverlay=true,recognizing=false,calibrationPair=null,recognitionController=null;
let wallCursor=null,wallPrevious=null;
let serviceStatus={vision:false,image3d:false};
function liveWallSegments(){return state.structure.walls.flatMap((w,i)=>state.demolished.includes('w'+i)?[]:C.solids(w,state.structure.openings).filter(p=>p.bottom<300).flatMap(p=>WallRegionsCore.solidIntervals(state,w,p.a,p.b).map(([a,b])=>({...w,a:C.point(w,a),b:C.point(w,b)}))));}
snapMove=function(f,cx,cy){let x=Math.round(cx/10)*10,y=Math.round(cy/10)*10;if(!ui.layers.wallSnap)return [x,y];const radius=aabb(f),tol=10/view.s;let best=tol;for(const w of liveWallSegments()){const a=C.frame(w),t=(cx-w.a[0])*a.ux+(cy-w.a[1])*a.uy,n=-(cx-w.a[0])*a.uy+(cy-w.a[1])*a.ux,rt=Math.abs(a.ux)*radius.hw+Math.abs(a.uy)*radius.hh,rn=Math.abs(a.uy)*radius.hw+Math.abs(a.ux)*radius.hh;if(t<-rt||t>a.l+rt)continue;const target=Math.sign(n||1)*(w.thickness/2+rn),delta=target-n;if(Math.abs(delta)<best){best=Math.abs(delta);x=cx-a.uy*delta;y=cy+a.ux*delta;}}return [Math.round(x),Math.round(y)];};
pushOut=function(f){for(let i=0;i<6;i++){let moved=false;for(const w of liveWallSegments()){const a=C.frame(w),r=aabb(f),t=(f.cx-w.a[0])*a.ux+(f.cy-w.a[1])*a.uy,n=-(f.cx-w.a[0])*a.uy+(f.cy-w.a[1])*a.ux,rt=Math.abs(a.ux)*r.hw+Math.abs(a.uy)*r.hh,rn=Math.abs(a.uy)*r.hw+Math.abs(a.ux)*r.hh;if(t<=-rt||t>=a.l+rt||Math.abs(n)>=w.thickness/2+rn)continue;const delta=Math.sign(n||1)*(w.thickness/2+rn)-n;f.cx-=a.uy*delta;f.cy+=a.ux*delta;moved=true;}if(!moved)break;}};
snapPoint=function(p,shift){let q={x:Math.round(p.x/10)*10,y:Math.round(p.y/10)*10},best=8/view.s;for(const w of state.structure.walls){const t=C.project(w,[p.x,p.y]);for(const n of [-w.thickness/2,w.thickness/2]){const a=C.point(w,t,n),d=Math.hypot(a[0]-p.x,a[1]-p.y);if(d<best){best=d;q={x:a[0],y:a[1]};}}}if(shift&&ui.mA){if(Math.abs(q.x-ui.mA.x)>Math.abs(q.y-ui.mA.y))q.y=ui.mA.y;else q.x=ui.mA.x;}return q;};
const originalRenderPanel=renderPanel,originalRenderSel=renderSel,originalMutate=mutate,originalSetTool=setTool,originalDelete=deleteSel;
const originalSetView=setView;
setView=async function(m){try{return await originalSetView(m);}catch(e){switching=false;viewMode='2d';document.body.classList.remove('busy','m3d');$('#stage').classList.remove('is3d','animating');toast('三维场景未能启动：'+e.message);console.error(e);}};
mutate=function(fn,options={}){const before=snap();try{fn();if(!options.calibration)C.assertLockedEdits(JSON.parse(before),state);C.validate(state);commit(before);renderAll();}catch(e){state=JSON.parse(before);syncDerived();renderAll();toast(e.message);}};
deleteSel=function(){if(ui.sel&&['wall','opening','column','room'].includes(ui.sel.kind)&&state.workflow==='structure'){const {kind,id}=ui.sel;ui.sel=null;mutate(()=>{const key={wall:'walls',opening:'openings',column:'columns',room:'rooms'}[kind];state.structure[key]=state.structure[key].filter(o=>o.id!==id);if(kind==='wall'){state.structure.openings=state.structure.openings.filter(o=>o.wallId!==id);state.structure.wallRegions=(state.structure.wallRegions||[]).filter(r=>r.wallId!==id);}if(kind==='room')delete state.rooms[id];state.demolished=[];});}else originalDelete();};
setTool=function(t){structTool='pick';draft=[];originalSetTool(t);updateStudio();};

