    $('[data-property="wallColor"]').onchange=e=>mutate(()=>state.rooms[id].wallColor=e.target.value);
    $('#panel section').insertAdjacentHTML('afterbegin',`<div class="form">${selField('spaceKind','空间类型',r.kind||'room',[['room','普通房间'],['balcony','阳台'],['bay_window','飘窗']])}${r.kind==='bay_window'?field('spaceElevation','飘窗台高（mm · 估算）',r.elevation||700):''}</div>`);
    $('[data-property="spaceKind"]').onchange=e=>mutate(()=>{r.kind=e.target.value;r.counted=r.kind!=='bay_window';if(r.kind==='bay_window')r.elevation=r.elevation||700;else delete r.elevation;});
