function mmPoint(e){const p=toMM(e);let q=[Math.round(p.x/10)*10,Math.round(p.y/10)*10];if(e.shiftKey&&draft.length){const a=draft.at(-1);if(Math.abs(q[0]-a[0])>Math.abs(q[1]-a[1]))q[1]=a[1];else q[0]=a[0];}return q;}
function rawStructurePoint(e){const p=toMM(e);return [p.x,p.y];}
function finishRoom(){if(draft.length<3)return toast('房间边界至少需要三个顶点');const points=C.clone(draft);draft=[];mutate(()=>{const id=C.id('room');state.structure.rooms.push({id,name:'未命名区域 '+(state.structure.rooms.length+1),poly:points,mat:'tile800',reviewed:false});ui.sel={kind:'room',id};});}
svg.addEventListener('pointerdown',e=>{
  if(state.workflow!=='structure'||ui.tool==='measure'||e.button!==0||e.target.closest('[data-fid]'))return;
  const p=structTool==='wall'?wallDrawPoint(e).point:mmPoint(e),handle=e.target.closest('[data-structure-handle]');
  if(structTool!=='pick'){e.preventDefault();e.stopImmediatePropagation();
    if(structTool==='door'||structTool==='window'){const nearest=C.nearest(state,p);if(!nearest||nearest.distance>Math.max(250,20/view.s))return toast('请点击要放置门窗的墙体');const w=nearest.wall,l=C.length(w),type=structTool==='door'?'door':'window',width=Math.min(type==='door'?900:1400,l);mutate(()=>{const o={id:C.id(type),wallId:w.id,type,width,offset:Math.max(0,Math.min(l-width,nearest.t-width/2)),height:Math.min(type==='door'?2100:1400,w.height-(type==='door'?0:900)),sill:type==='door'?0:900,reviewed:false};state.structure.openings.push(o);ui.sel={kind:'opening',id:o.id};});return;}
    if(structTool==='wall'){
      if(!draft.length){draft=[p];wallPrevious=null;wallCursor=null;ui.sel=null;renderSel();return;}
      const a=draft.at(-1);if(Math.hypot(p[0]-a[0],p[1]-a[1])<10)return;
      let end=null;mutate(()=>{const w=C.wall(a,p);state.structure.walls.push(w);C.snapWall(state,w.id,1,view.s,!e.altKey||e.shiftKey);end=[...state.structure.walls.find(o=>o.id===w.id).b];ui.sel=null;});
      if(end){wallPrevious=[...a];draft=[end];wallCursor=null;}renderSel();return;
    }
    draft.push(p);
    if(structTool==='column'&&draft.length===2){const [a,b]=draft;draft=[];mutate(()=>{const c={id:C.id('column'),x:(a[0]+b[0])/2,y:(a[1]+b[1])/2,w:Math.abs(b[0]-a[0]),d:Math.abs(b[1]-a[1]),height:2800,reviewed:false};state.structure.columns.push(c);ui.sel={kind:'column',id:c.id};});}
    if(structTool==='calibrate'&&draft.length===2){calibrationPair=C.clone(draft);draft=[];$('#calibrateDialog').showModal();}renderSel();return;
  }
  let hit=handle?ui.sel:null;const target=e.target.closest('[data-wall],[data-column],[data-opening]');if(target){hit=target.dataset.wall?{kind:'wall',id:target.dataset.wall}:target.dataset.column?{kind:'column',id:target.dataset.column}:{kind:'opening',id:target.dataset.opening};}
  if(!hit)return;e.preventDefault();e.stopImmediatePropagation();select(hit);updateStudio();const w=hit.kind==='wall'?state.structure.walls.find(w=>w.id===hit.id):hit.kind==='opening'?state.structure.walls.find(w=>w.id===state.structure.openings.find(o=>o.id===hit.id)?.wallId):null;if(C.isLocked(w))return;structureDrag={id:hit.id,kind:hit.kind,handle:handle?.dataset.structureHandle,index:Number(handle?.dataset.index),start:handle?.dataset.structureHandle==='wall-end'?rawStructurePoint(e):p,before:snap(),moved:false,axisLocked:true,pid:e.pointerId};svg.setPointerCapture(e.pointerId);
},true);
svg.addEventListener('pointermove',e=>{if(state.workflow==='structure'&&structTool==='wall'&&draft.length&&!structureDrag){wallCursor=wallDrawPoint(e);renderSel();}if(!structureDrag||e.pointerId!==structureDrag.pid)return;e.stopImmediatePropagation();const d=structureDrag,p=d.handle==='wall-end'?rawStructurePoint(e):mmPoint(e),base=JSON.parse(d.before),dx=p[0]-d.start[0],dy=p[1]-d.start[1];if(!d.moved&&Math.hypot(dx,dy)*view.s<3)return;d.moved=true;if(d.kind==='wall'){state.structure.walls=C.clone(base.structure.walls);state.structure.openings=C.clone(base.structure.openings);}const key={wall:'walls',column:'columns',opening:'openings',room:'rooms'}[d.kind],o=state.structure[key].find(o=>o.id===d.id),old=base.structure[key].find(o=>o.id===d.id);
  if(d.handle==='room-vertex'){o.poly[d.index]=p;delete o.at;}else if(d.kind==='wall'){if(d.handle==='wall-end'){const resize=C.dragWallEnd(old,d.index,[dx,dy],view.s,d.axisLocked,e.shiftKey);d.axisLocked=resize.locked;o[d.index===0?'a':'b']=resize.point;$('#structureTip').textContent=d.axisLocked?'沿原墙方向伸缩 · 明显向两侧拖动可调整角度 · Shift 保持原方向':'正在调整墙体角度 · 回到原方向附近自动吸附 · Shift 保持原方向';}else{o.a=[old.a[0]+dx,old.a[1]+dy];o.b=[old.b[0]+dx,old.b[1]+dy];}}else if(d.kind==='column'){o.x=old.x+dx;o.y=old.y+dy;}else if(d.kind==='opening'){const w=state.structure.walls.find(w=>w.id===o.wallId);o.offset=Math.max(0,Math.min(C.length(w)-o.width,C.project(w,p)-o.width/2));}o.reviewed=false;if(d.kind==='wall'){d.joinSnap=C.snapWall(state,d.id,d.handle==='wall-end'?d.index:'move',view.s,d.handle==='wall-end'&&d.axisLocked);if(d.joinSnap)document.querySelector('#structureTip').textContent='已吸附接合墙体 · 松手保留连接，继续拖离可分开';}syncDerived();renderRooms();renderWalls();renderDims();renderSel();renderLabels();},true);
function endStructureDrag(e){if(!structureDrag||e.pointerId!==structureDrag.pid)return;e.stopImmediatePropagation();const d=structureDrag;structureDrag=null;if(e.type==='pointercancel'){state=JSON.parse(d.before);}else if(d.moved){try{C.validate(state);commit(d.before);}catch(err){state=JSON.parse(d.before);toast(err.message);}}renderAll();}
svg.addEventListener('pointerleave',()=>{wallCursor=null;renderSel();});
svg.addEventListener('pointerup',endStructureDrag,true);svg.addEventListener('pointercancel',endStructureDrag,true);
addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='Escape'){draft=[];wallCursor=null;wallPrevious=null;structTool='pick';renderSel();updateStudio();}if(e.key==='Enter'&&structTool==='room')finishRoom();if(e.key==='Enter'&&structTool==='wall'){e.preventDefault();finishWallChain();}},true);
$('#applyCalibration').onclick=()=>{const actual=Number($('#actualDistance').value),distance=calibrationPair&&Math.hypot(calibrationPair[1][0]-calibrationPair[0][0],calibrationPair[1][1]-calibrationPair[0][1]);if(actual<=0||distance<1||!Number.isFinite(actual))return toast('请输入有效的实际长度');mutate(()=>{C.scale(state,actual/distance);state.calibration={confirmed:true,method:'two-point',actual,points:calibrationPair};},{calibration:true});$('#calibrateDialog').close();fitView();};

let pendingImage=null,furnitureReference=null,pendingModel=null;
function fileData(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(Error('读取文件失败'));r.readAsDataURL(file);});}
async function readImage(file){if(!file||!['image/png','image/jpeg'].includes(file.type))throw Error('请选择 PNG 或 JPG 图片');if(file.size>15*1024*1024)throw Error('图片请小于 15 MB');const data=await fileData(file),img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('图片无法解码'));img.src=data;});if(img.width*img.height>40e6)throw Error('图片过大，请缩小到 4000 万像素以内');return {data,width:img.width,height:img.height,name:file.name,mmPerPixel:10000/img.width};}
async function choosePlanImage(file){pendingImage=null;$('#uploadPreview').innerHTML='';try{pendingImage=await readImage(file);$('#uploadPreview').innerHTML=`<img src="${pendingImage.data}" alt="上传的户型原图">`;$('#uploadInfo').textContent=`${pendingImage.name} · ${pendingImage.width} × ${pendingImage.height} px · 待识别、待比例校准`;if(!$('#uploadDialog').open)$('#uploadDialog').showModal();}catch(e){toast(e.message);}}
$('#dialogImage').onchange=e=>choosePlanImage(e.target.files[0]);$('#planImageInput').onchange=e=>choosePlanImage(e.target.files[0]);
$('#imageDrop').ondragover=e=>{e.preventDefault();e.currentTarget.classList.add('drag-over');};$('#imageDrop').ondragleave=e=>e.currentTarget.classList.remove('drag-over');$('#imageDrop').ondrop=e=>{e.preventDefault();e.currentTarget.classList.remove('drag-over');choosePlanImage(e.dataTransfer.files[0]);};
function startImagePlan(){const s=C.blank();s.title=pendingImage.name.replace(/\.[^.]+$/,'');s.source=C.clone(pendingImage);return s;}
async function applyImagePlan(s){C.validate(s);if(is3D())await setView('2d');const before=snap();state=s;ui.sel=null;window.emptyStarted=true;commit(before);$('#uploadDialog').close();renderAll();fitView();}
$('#manualTrace').onclick=()=>{if(!pendingImage)return toast('请先选择户型图片');applyImagePlan(startImagePlan());};
async function refreshRecognitionStatus(){
 try{serviceStatus=await(await fetch('/api/status')).json();const local=serviceStatus.localAI;$('#localRecognize').disabled=!local?.available;$('#localRecognize').title=local?.available?'单独使用本机已安装的 CubiCasa 模型':'本机未安装模型及运行库；仍可使用视觉 API 或手动描绘';
  $('#visionStatus').textContent=serviceStatus.vision?'已启用网页设置中的视觉 API · 主识别入口直接调用该 API。'+(local?.available?' 本机 CubiCasa 可单独选择。':' 本机 CubiCasa 未安装。'):local?.state==='ready'?'本机户型模型已就绪 · 新图片均重新推理，无需 API Key。':local?.available?(local.state==='error'?'本机模型未能启动：'+local.error:'本机户型模型正在加载，首次识别会等待加载完成。'):serviceStatus.vision?'已配置视觉 API，可识别新图。':'没有可用的智能识别服务。可以使用基础线条提取与手动描绘。';
 }catch{$('#visionStatus').textContent='未连接本地服务，请先启动网页服务。';}
}
async function planVisionInput(source){return {image:source.data,width:source.width,height:source.height,sourceWidth:source.width,sourceHeight:source.height};}
async function recognizeImage(requested='auto',feedback=''){
 if(recognizing)return;if(!pendingImage)return toast('请先选择户型图片');
 const source=pendingImage,provider=requested===true?'vision':requested===false?'auto':requested;
 recognizing=true;recognitionController=new AbortController();for(const id of ['localRecognize','cloudRecognize','basicRecognize'])$('#'+id).disabled=true;
 try{
  const s=startImagePlan();s.recognition={method:provider==='local'?'cubicasa':provider==='basic'?'local-pixels':'vision-api',status:'processing',message:'原图已载入，正在识别当前图片…'};await applyImagePlan(s);let result;
  if(provider==='basic'){
   $('#uploadInfo').textContent='正在提取基础线条；此入口不进行完整语义识别。';await new Promise(requestAnimationFrame);result=await FloorRecognition.recognize(source,$('#symbolConvention').checked);
   result.recognition.status=result.structure.walls.length?'partial':'failed';result.recognition.message='基础线条辅助结果，不代表完整门窗或阳台识别。'+result.recognition.message;
  }else{
   await refreshRecognitionStatus();const useVision=provider!=='local';
   if(useVision&&!serviceStatus.vision)throw Error('视觉 API 尚未配置，请在设置中保存并启用支持识图的接口；也可手动描绘');
   if(!useVision&&!serviceStatus.localAI?.available)throw Error('本机户型模型未安装，且未配置视觉 API。智能识别尚不可用');
   $('#uploadInfo').textContent=useVision?'正在调用已配置的视觉服务识别当前新图片…':'正在用本机模型识别当前图片的墙体、门窗和空间，再转换为可编辑结构…';
   const visionInput=useVision?await planVisionInput(source):{image:source.data,width:source.width,height:source.height};const response=await fetch(useVision?'/api/recognize-stream':'/api/recognize-local',{method:'POST',headers:{'Content-Type':'application/json'},signal:recognitionController.signal,body:JSON.stringify({...visionInput,feedback,symbolConvention:$('#symbolConvention').checked})});
   result=useVision?await SceneExtractionStream.read(response,event=>{$('#uploadInfo').textContent=event.text||'正在识别结构…';}):await response.json();if(!response.ok)throw Error(result.error||'识别服务请求失败');
   if(useVision)result.recognition=result.recognition||{diagnostics:result.diagnostics,method:'vision-api',status:'needs-review',unresolved:result.unresolved||[],message:'视觉 API 当前图片候选结构。'+(result.notes||'')};
  }
  // Never apply a delayed response to a different image selected in the meantime.
  if(pendingImage!==source)return;
  s.structure=result.structure;s.recognition=result.recognition;
  if(result.calibration?.mmPerPixel){s.calibration=result.calibration;s.source.mmPerPixel=result.calibration.mmPerPixel;}
  const hasStructure=s.structure.walls.length||s.structure.rooms.length;
  if(!hasStructure){s.recognition.status='failed';s.recognition.message='未获得可靠结构，不能视为识别完成。可重新识别、换清晰图片或手动描绘。 '+s.recognition.message;}
  for(const x of [...s.structure.walls,...s.structure.openings,...s.structure.columns,...s.structure.rooms]){x.reviewed=false;if(x.a)x.bearing='unknown';}
  await applyImagePlan(s);toast(hasStructure?'已生成当前图片的候选结构，请检查门窗与空间':'未识别出可靠结构，请重新识别或手动描绘');
 }catch(e){if(pendingImage===source){state.recognition={...state.recognition,status:'failed',message:'识别未完成：'+e.message,errorCode:e.code||'RECOGNITION_FAILED'};save();renderAll();$('#uploadInfo').textContent='识别未完成：'+e.message+'。当前结果不会标为成功，可重试或手动描绘。';toast(e.message);}}
 finally{recognizing=false;for(const id of ['localRecognize','cloudRecognize','basicRecognize'])$('#'+id).disabled=id==='localRecognize'&&!serviceStatus.localAI?.available;updateStudio();}
}
$('#localRecognize').onclick=()=>recognizeImage('local');$('#cloudRecognize').onclick=()=>recognizeImage('vision');$('#basicRecognize').onclick=()=>recognizeImage('basic');
$('#retryPlanRecognition').onclick=()=>{if(!state.source)return toast('请先上传原图');pendingImage=C.clone(state.source);$('#uploadPreview').innerHTML=`<img src="${pendingImage.data}" alt="待重新识别的户型原图">`;$('#uploadInfo').textContent='当前原图已载入，可重新运行智能识别。';$('#uploadDialog').showModal();refreshRecognitionStatus();};
refreshRecognitionStatus();

$('#importFurnitureImage').onclick=()=>$('#furnitureImageInput').click();$('#importModel').onclick=()=>$('#modelInput').click();
$('#furnitureImageInput').onchange=async e=>{try{furnitureReference=await readImage(e.target.files[0]);$('#furniturePreview').innerHTML=`<img src="${furnitureReference.data}" alt="家具参考图">`;$('#furnitureDialog').showModal();}catch(err){toast(err.message);}e.target.value='';};
function placement(){const room=ui.sel?.kind==='room'&&state.structure.rooms.find(r=>r.id===ui.sel.id);return room?C.center(room.poly):[view.x0+svg.clientWidth/2/view.s,view.y0+svg.clientHeight/2/view.s];}
$('#createApprox').onclick=()=>{const w=Number($('#approxW').value),d=Number($('#approxD').value),h=Number($('#approxH').value);if(Math.min(w,d,h)<50||![w,d,h].every(Number.isFinite))return toast('请输入有效的实际尺寸');const [x,y]=placement(),type=$('#approxType').value;mutate(()=>{const f=F(type,'近似模型 · '+$('#approxType').selectedOptions[0].textContent,x,y,w,d,0,$('#approxColor').value);Object.assign(f,{h,approximate:true,reference:furnitureReference.data,material:'original'});state.furniture.push(f);ui.sel={kind:'furn',id:f.id};});$('#furnitureDialog').close();};
$('#modelInput').onchange=async e=>{try{if(!window.View3D)throw Error('三维引擎尚未加载');const files=[...e.target.files],main=files.find(f=>/\.(glb|gltf)$/i.test(f.name));if(!main)throw Error('请选择 GLB 或 GLTF 文件');if(files.reduce((n,f)=>n+f.size,0)>30*1024*1024)throw Error('模型和纹理合计请小于 30 MB');let asset={id:C.id('asset'),name:main.name,kind:/\.glb$/i.test(main.name)?'glb':'gltf'};if(asset.kind==='glb')asset.data=await fileData(main);else{const json=JSON.parse(await main.text());for(const list of [json.buffers||[],json.images||[]])for(const entry of list)if(entry.uri&&!entry.uri.startsWith('data:')){const name=decodeURIComponent(entry.uri).split('/').at(-1),resource=files.find(f=>f.name===name);if(!resource)throw Error('缺少配套文件 '+name+'，请连同模型一起选择');entry.uri=await fileData(resource);}asset.data=JSON.stringify(json);}const size=await View3D.importModel(asset);pendingModel=asset;$('#modelInfo').textContent=asset.name+' · 模型已解析，请确认实际尺寸';$('#modelW').value=size.w;$('#modelD').value=size.d;$('#modelH').value=size.h;$('#modelDialog').showModal();}catch(err){toast('模型导入失败：'+err.message);}e.target.value='';};
$('#placeModel').onclick=()=>{const w=Number($('#modelW').value),d=Number($('#modelD').value),h=Number($('#modelH').value);if(!pendingModel||Math.min(w,d,h)<10||![w,d,h].every(Number.isFinite))return toast('请输入有效尺寸');const [x,y]=placement();mutate(()=>{state.assets[pendingModel.id]=pendingModel;const f=F('asset',pendingModel.name,x,y,w,d,0,'#c6a580');f.assetId=pendingModel.id;f.h=h;state.furniture.push(f);ui.sel={kind:'furn',id:f.id};});$('#modelDialog').close();};

// IndexedDB fallback retains full embedded images/models when localStorage quota is exceeded.
function planDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('floorplan-studio-stage-01',1);r.onupgradeneeded=()=>r.result.createObjectStore('plans');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
window.persistLargePlan=async(s,revision)=>{const payload=C.clone(s);try{const db=await planDB();await new Promise((res,rej)=>{const tx=db.transaction('plans','readwrite');tx.objectStore('plans').put(payload,'current');tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});if(revision===window.localSaveRevision&&window.localSaveFailed)localStorage.setItem(STORE,JSON.stringify({largePlan:true}));db.close();}catch(e){toast('本地空间不足，请导出 JSON 保存方案');}};
async function restoreLargePlan(){try{const marker=JSON.parse(localStorage.getItem(STORE));if(!marker?.largePlan)return;const db=await planDB(),s=await new Promise((res,rej)=>{const r=db.transaction('plans').objectStore('plans').get('current');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});if(s){state=C.validate(s);renderAll();fitView();}db.close();}catch(e){toast('本地方案读取失败，请导入备份');}}
applyStaticLang();syncFullscreen();buildDefs();buildLib();$('#tip').textContent=TIPS()['2d'];fitView();renderAll();window.planRestorationReady=restoreLargePlan();
window.Studio={getState:()=>C.clone(state),importPlan:s=>{const next=fixState(C.clone(s)),b=snap();state=next;ui.sel=null;commit(b);renderAll();fitView();},exportPlan:()=>JSON.stringify(state),structure:enterStructure,furniture:enterFurniture,select,getView:()=>({...view}),draw:drawingTool,undo,redo,addItem,calibrate:(a,b,actual)=>{calibrationPair=[a,b];$('#actualDistance').value=actual;$('#applyCalibration').click();},recognize:recognizeImage,chooseImage:choosePlanImage};

